python3 -I -c 'import pathlib,tempfile,subprocess,os,shutil,json; root=pathlib.Path.cwd(); source=(root/"benchmark/scripts/split_allocate.py").read_text(); env=dict(os.environ); env.pop("LABVIEW_ENVIRONMENT",None); probes=[("baseline",source),("return before reason self-test",source.replace("    def actual_reason():","    return\n\n    def actual_reason():",1)),("return after first mutation (sequential calls; no mutation loop exists)",source.replace("    mutation(\u0027group split across partitions\u0027, \u0027group split across partitions: SYN-G1\u0027, split_group)","    mutation(\u0027group split across partitions\u0027, \u0027group split across partitions: SYN-G1\u0027, split_group)\n    return",1)),("remove one mutation",source.replace("    mutation(\u0027group split across partitions\u0027, \u0027group split across partitions: SYN-G1\u0027, split_group)\n","",1)),("compare only first reason character",source.replace("require(str(exc) == reason,","require(str(exc)[:1] == reason[:1],",1))]; results=[]; print("REPOSITORY VERIFICATION"); baseline=subprocess.run(["python3","-I","-B","benchmark/scripts/split_allocate.py","--check"],env=env,capture_output=True,text=True); print(json.dumps({"exit":baseline.returncode,"stdout":baseline.stdout,"stderr":baseline.stderr}));
with tempfile.TemporaryDirectory(prefix="review449-") as td:
 p=pathlib.Path(td); (p/"benchmark/scripts").mkdir(parents=True); (p/"benchmark/split").mkdir();
 for name in ("allocation.synthetic.json","allocation-manifest.template.json"): shutil.copyfile(root/"benchmark/split"/name,p/"benchmark/split"/name)
 for name,code in probes:
  if name!="baseline" and code==source: raise RuntimeError("probe replacement failed: "+name)
  script=p/"benchmark/scripts/split_allocate.py"; script.write_text(code); r=subprocess.run(["python3","-I","-B",str(script),"--check"],env=env,capture_output=True,text=True); results.append({"probe":name,"exit":r.returncode,"stderr":r.stderr.strip(),"stdout":r.stdout})
print("PROBE RESULTS"); print(json.dumps(results,indent=2))'

